//! Baked Catmull-Clark eigenstructure coefficients.
//!
//! Auto-generated by `cargo bake-eigen` from ccdata50NT.dat.
//! Do not edit manually.
//!
//! Source: Stam, "Exact Evaluation of Catmull-Clark Subdivision Surfaces"
//! Data from: https://www.dgp.toronto.edu/~stam/reality/Research/SubdivEval/

/// Maximum supported valence.
pub const MAX_VALENCE: usize = 50;

/// Eigenstructure data for a specific valence.
#[derive(Clone, Debug)]
pub struct EigenCoeffs {
    /// Valence (number of edges at extraordinary vertex)
    pub valence: usize,
    /// K = 2N + 8 (number of eigenvalues/bases)
    pub k: usize,
    /// Eigenvalues (K values)
    pub eigenvalues: &'static [f32],
    /// Inverse eigenvector matrix (K×K, row-major)
    pub inv_eigenvectors: &'static [f32],
    /// Spline coefficients [subpatch][basis][coeff] flattened
    /// Layout: 3 subpatches × K bases × 16 bicubic coeffs
    pub spline_coeffs: &'static [f32],
}

impl EigenCoeffs {
    /// Get spline coefficient for subpatch, basis, and coefficient index.
    #[inline]
    #[must_use]
    pub fn spline(&self, subpatch: usize, basis: usize, coeff: usize) -> f32 {
        self.spline_coeffs[subpatch * self.k * 16 + basis * 16 + coeff]
    }

    /// Get inverse eigenvector matrix element.
    #[inline]
    #[must_use]
    pub fn inv_eigen(&self, row: usize, col: usize) -> f32 {
        self.inv_eigenvectors[row * self.k + col]
    }
}

